#include <iostream>
#include <unordered_map>
using namespace std;
​
// 记忆化缓存
unordered_map<int, int> memo;
​
// f(m): 返回最终会分成的份数（每份 <= 2）
int f(int m) {
    if (m <= 2) return 1; // 叶子节点情况
    if (memo.count(m)) return memo[m];
    int a = f(m / 2);
    int b = f((m + 1) / 2);
    return memo[m] = a + b;
}
​
int main() {
    int m;
    cin >> m;
    int parts = f(m);        // 最终份数
    int splits = parts - 1;  // 分的次数
    cout << splits << " " << parts;
    return 0;
}
