import java.util.*;
​
public class Main {
    static Map<Integer, Integer> memo = new HashMap<>();
​
    // f(m): 返回最终会分成的份数（每份 <= 2）
    static int f(int m) {
        if (m <= 2) return 1; // 叶子节点情况
        if (memo.containsKey(m)) return memo.get(m);
        int a = f(m / 2);
        int b = f((m + 1) / 2);
        int res = a + b;
        memo.put(m, res);
        return res;
    }
​
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int m = sc.nextInt();
        int parts = f(m);        // 最终份数
        int splits = parts - 1;  // 分的次数
        System.out.println(splits + " " + parts);
    }
}
