  input: process.stdin,
  output: process.stdout
});
​
const memo = new Map();
​
// f(m): 返回最终会分成的份数（每份 <= 2）
function f(m) {
  if (m <= 2) return 1; // 叶子节点情况
  if (memo.has(m)) return memo.get(m);
  const a = f(Math.floor(m / 2));
  const b = f(Math.floor((m + 1) / 2));
  const res = a + b;
  memo.set(m, res);
  return res;
}
​
rl.on("line", (line) => {
  const m = parseInt(line.trim());
  const parts = f(m);        // 最终份数
  const splits = parts - 1;  // 分的次数
  console.log(splits + " " + parts);
});
