package main
​
import (
    "fmt"
)
​
// 记忆化缓存
var memo = make(map[int]int)
​
// f(m): 返回最终会分成的份数（每份 <= 2）
func f(m int) int {
    if m <= 2 {
        return 1 // 叶子节点情况
    }
    if val, ok := memo[m]; ok {
        return val
    }
    a := f(m / 2)
    b := f((m + 1) / 2)
    memo[m] = a + b
    return memo[m]
}
​
func main() {
    var m int
    fmt.Scan(&m)
    parts := f(m)        // 最终份数
    splits := parts - 1  // 分的次数
    fmt.Printf("%d %d\n", splits, parts)
}
